import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import VoterVerify from "./pages/VoterVerify";
import BallotPage from "./pages/BallotPage";
import VoteSuccess from "./pages/VoteSuccess";
import AdminLogin from "./pages/AdminLogin";
import ResultsPage from "./pages/ResultsPage";


function App() {
  const [voterHash, setVoterHash] = useState("");
  const [token, setToken] = useState("");

  return (
    <Router>
      <Routes>
        <Route path="/" element={<VoterVerify setVoterHash={setVoterHash} />} />
        <Route path="/ballot" element={<BallotPage voterHash={voterHash} />} />
        <Route path="/success" element={<VoteSuccess />} />
        <Route path="/admin" element={<AdminLogin setToken={setToken} />} />
        <Route path="/results" element={<ResultsPage token={token} />} />
      </Routes>
    </Router>
  );
}

export default App;
